SELECT MONTH(customers.signup_date) AS signup_month, customers.segment, ROUND((100 * SUM(CASE WHEN transactions.txn_type = 'REFUND' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_refund FROM transactions LEFT JOIN accounts ON accounts.id = transactions.account_id JOIN customers ON accounts.customer_id = customers.id GROUP BY MONTH(customers.signup_date), customers.segment ORDER BY pct_refund;
